    {"offset": {"line": 226, "column": 0}, "map": {"version":3,"sources":["file:///C:/myprojects/intellibus/intellicare/components/footer.tsx"],"sourcesContent":["export default function Footer() {\n  return (\n    <footer className=\"bg-secondary text-secondary-foreground border-t border-border\">\n      <div className=\"max-w-6xl mx-auto px-4 py-12\">\n        <div className=\"grid md:grid-cols-4 gap-8 mb-8\">\n          <div>\n            <h3 className=\"font-semibold mb-4\">Intellibus Care</h3>\n            <p className=\"text-sm opacity-75\">Connecting healthcare professionals with communities in need.</p>\n          </div>\n          <div>\n            <h4 className=\"font-semibold mb-4\">Quick Links</h4>\n            <ul className=\"space-y-2 text-sm\">\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  About\n                </a>\n              </li>\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  Doctors\n                </a>\n              </li>\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  Register\n                </a>\n              </li>\n            </ul>\n          </div>\n          <div>\n            <h4 className=\"font-semibold mb-4\">Support</h4>\n            <ul className=\"space-y-2 text-sm\">\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  FAQ\n                </a>\n              </li>\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  Contact\n                </a>\n              </li>\n              <li>\n                <a href=\"#\" className=\"opacity-75 hover:opacity-100\">\n                  Help\n                </a>\n              </li>\n            </ul>\n          </div>\n          <div>\n            <h4 className